-- WhatsApp-approval site access gate.
-- Client inserts inquiries.access_token; this trigger creates a pending site_access_requests row.
-- Visitors poll get_access_status(token) (SECURITY DEFINER) — anon has no direct SELECT on the table.
-- Owner Approve/Reject is applied via resolve_site_access_request (pending-only / idempotent).

create extension if not exists pgcrypto;

-- 1) Token column on inquiries (generated by the public form, stored for traceability)
alter table public.inquiries
  add column if not exists access_token uuid;

create unique index if not exists inquiries_access_token_uidx
  on public.inquiries (access_token)
  where access_token is not null;

-- 2) Access-request rows the gate polls
create table if not exists public.site_access_requests (
  id uuid primary key default gen_random_uuid(),
  inquiry_id uuid references public.inquiries(id) on delete set null,
  access_token uuid not null unique,
  visitor_name text,
  visitor_phone text,
  visitor_email text,
  event_type text,
  venue text,
  status text not null default 'pending'
    check (status in ('pending', 'approved', 'rejected')),
  decided_at timestamptz,
  decided_by text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists site_access_requests_status_idx
  on public.site_access_requests (status, created_at desc);

create index if not exists site_access_requests_phone_idx
  on public.site_access_requests (visitor_phone);

create or replace function public.site_access_requests_set_updated_at()
returns trigger
language plpgsql
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

drop trigger if exists site_access_requests_set_updated_at on public.site_access_requests;
create trigger site_access_requests_set_updated_at
  before update on public.site_access_requests
  for each row execute procedure public.site_access_requests_set_updated_at();

-- 3) After inquiry INSERT with an access_token, create the pending request
create or replace function public.create_site_access_request_from_inquiry()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if new.access_token is null then
    return new;
  end if;

  insert into public.site_access_requests (
    inquiry_id,
    access_token,
    visitor_name,
    visitor_phone,
    visitor_email,
    event_type,
    venue,
    status
  )
  values (
    new.id,
    new.access_token,
    new.name,
    new.phone,
    new.email,
    new.event_type,
    new.venue,
    'pending'
  )
  on conflict (access_token) do nothing;

  return new;
end;
$$;

drop trigger if exists create_site_access_request_from_inquiry on public.inquiries;
create trigger create_site_access_request_from_inquiry
  after insert on public.inquiries
  for each row execute procedure public.create_site_access_request_from_inquiry();

grant execute on function public.create_site_access_request_from_inquiry() to anon, authenticated;

-- 4) Visitor-facing status check (no row leakage)
create or replace function public.get_access_status(p_token uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  rec public.site_access_requests%rowtype;
begin
  if p_token is null then
    return jsonb_build_object('status', 'none');
  end if;

  select * into rec
  from public.site_access_requests
  where access_token = p_token
  limit 1;

  if not found then
    return jsonb_build_object('status', 'none');
  end if;

  return jsonb_build_object(
    'status', rec.status,
    'decided_at', rec.decided_at,
    'created_at', rec.created_at
  );
end;
$$;

revoke all on function public.get_access_status(uuid) from public;
grant execute on function public.get_access_status(uuid) to anon, authenticated;

-- 5) Idempotent owner decision (status changes only from pending)
create or replace function public.resolve_site_access_request(
  p_token uuid,
  p_status text,
  p_decided_by text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  rec public.site_access_requests%rowtype;
begin
  if p_status not in ('approved', 'rejected') then
    raise exception 'status must be approved or rejected';
  end if;

  update public.site_access_requests
  set
    status = p_status,
    decided_at = now(),
    decided_by = nullif(p_decided_by, '')
  where access_token = p_token
    and status = 'pending'
  returning * into rec;

  if not found then
    select * into rec
    from public.site_access_requests
    where access_token = p_token
    limit 1;

    if not found then
      return jsonb_build_object('ok', false, 'reason', 'not_found');
    end if;

    return jsonb_build_object(
      'ok', true,
      'changed', false,
      'status', rec.status,
      'visitor_phone', rec.visitor_phone,
      'visitor_name', rec.visitor_name
    );
  end if;

  return jsonb_build_object(
    'ok', true,
    'changed', true,
    'status', rec.status,
    'visitor_phone', rec.visitor_phone,
    'visitor_name', rec.visitor_name
  );
end;
$$;

revoke all on function public.resolve_site_access_request(uuid, text, text) from public;
grant execute on function public.resolve_site_access_request(uuid, text, text) to service_role, authenticated;

-- 6) RLS — visitors never read/write this table directly
alter table public.site_access_requests enable row level security;

drop policy if exists site_access_requests_select_admins on public.site_access_requests;
create policy site_access_requests_select_admins
  on public.site_access_requests for select
  using (auth.uid() in (select id from public.admin_users));

drop policy if exists site_access_requests_update_admins on public.site_access_requests;
create policy site_access_requests_update_admins
  on public.site_access_requests for update
  using (auth.uid() in (select id from public.admin_users));

grant select, update on public.site_access_requests to authenticated;
grant all on public.site_access_requests to service_role;

-- Realtime (admin UI later; visitors poll the RPC)
do $$
begin
  if not exists (
    select 1 from pg_publication_tables
    where pubname = 'supabase_realtime' and tablename = 'site_access_requests'
  ) then
    alter publication supabase_realtime add table public.site_access_requests;
  end if;
end $$;
